const items = $input.all();
const tree = items[0]?.json?.tree || [];
const processed = [];

// Filter for official markdown files in docs/ folder
const docFiles = tree.filter(file => 
  file.path && 
  file.path.startsWith('docs/') && 
  file.path.endsWith('.md') && 
  !file.path.includes('.github')
);

for (const file of docFiles) {
  const pathParts = file.path.split('/');
  const category = pathParts.length > 2 ? pathParts[1] : 'general';
  const fileName = pathParts[pathParts.length - 1].replace('.md', '');
  const title = fileName.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  const rawUrl = `https://raw.githubusercontent.com/n8n-io/n8n-docs/main/${file.path}`;

  processed.push({
    json: {
      metadata: {
        doc_type: 'official_doc',
        category: category,
        file_path: file.path,
        title: title,
        raw_url: rawUrl
      }
    }
  });
}

return processed;

const items = $input.all();
const processed = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // Explicitly reference upstream node metadata
  const metadata = $('Parse Doc File List').all()[i]?.json?.metadata || {};
  const fileContent = typeof item.json.data === 'string' ? item.json.data : (typeof item.json === 'string' ? item.json : '');

  if (!fileContent || fileContent.trim().length === 0) continue;

  const cleanContent = fileContent.trim();
  const sections = cleanContent.split(/(?=\n#{1,3}\s)/g);

  // Extract target node accurately from path (handles README.md, sub-pages, and folder structures)
  let targetNode = null;
  if (metadata.file_path) {
    const nodePackageMatch = metadata.file_path.match(/(n8n-nodes-[^\/]+)/);
    if (nodePackageMatch) {
      targetNode = nodePackageMatch[1].replace('.md', '');
    } else if (metadata.file_path.includes('integrations/') || metadata.file_path.includes('nodes/')) {
      const pathParts = metadata.file_path.split('/');
      const fileName = pathParts.pop().replace('.md', '');
      targetNode = (fileName.toLowerCase() === 'readme' || fileName.toLowerCase() === 'index') 
        ? pathParts.pop() 
        : fileName;
    }
  }

  let chunkIndex = 1;
  for (const section of sections) {
    const trimmed = section.trim();
    if (trimmed.length < 50) continue;

    const headingMatch = trimmed.match(/^#{1,3}\s+(.+)$/m);
    const sectionHeading = headingMatch ? headingMatch[1].replace(/[*_~`]/g, '') : 'General Overview';

    // Developer feature detection
    const hasCodeBlock = /```[a-z]*/i.test(trimmed);
    const hasJsonExample = /```json|\{[\s\S]*?\}/i.test(trimmed);
    const hasN8nExpression = /\{\{.*?\}\}/.test(trimmed) || /\$(json|input|node|vars|env|execution|workflow|prevNode)/.test(trimmed);
    const hasJsCode = /```(javascript|js)\b/i.test(trimmed) || /const\s+|let\s+|return\s+\[/.test(trimmed);
    const hasPythonCode = /```(python|py)\b/i.test(trimmed) || /def\s+|import\s+/.test(trimmed);
    const isNodeDoc = metadata.file_path ? (metadata.file_path.includes('integrations/') || metadata.file_path.includes('nodes/')) : false;

    const enrichedMetadata = {
      ...metadata,
      section_heading: sectionHeading,
      target_node: targetNode,
      has_code_block: hasCodeBlock,
      has_json_example: hasJsonExample,
      has_n8n_expression: hasN8nExpression,
      has_javascript: hasJsCode,
      has_python: hasPythonCode,
      is_node_doc: isNodeDoc
    };

    const maxChunkLen = 1500;

    if (trimmed.length > maxChunkLen) {
      const paragraphs = trimmed.split(/\n\n+/);
      let currentChunk = '';

      for (const para of paragraphs) {
        if ((currentChunk + '\n\n' + para).length > maxChunkLen && currentChunk.length > 0) {
          processed.push({
            json: {
              pageContent: `### ${metadata.title || 'Doc'} > ${sectionHeading} (Part ${chunkIndex})\n**Category:** ${metadata.category || 'general'}\n**Source:** ${metadata.file_path || ''}\n\n${currentChunk}`,
              metadata: {
                ...enrichedMetadata,
                chunk_index: chunkIndex,
                chunk_char_length: currentChunk.length
              }
            }
          });
          chunkIndex++;
          currentChunk = para;
        } else {
          currentChunk = currentChunk ? `${currentChunk}\n\n${para}` : para;
        }
      }

      if (currentChunk.trim().length > 30) {
        processed.push({
          json: {
            pageContent: `### ${metadata.title || 'Doc'} > ${sectionHeading} (Part ${chunkIndex})\n**Category:** ${metadata.category || 'general'}\n**Source:** ${metadata.file_path || ''}\n\n${currentChunk}`,
            metadata: {
              ...enrichedMetadata,
              chunk_index: chunkIndex,
              chunk_char_length: currentChunk.length
            }
          }
        });
        chunkIndex++;
      }
    } else {
      processed.push({
        json: {
          pageContent: `### ${metadata.title || 'Doc'} > ${sectionHeading}\n**Category:** ${metadata.category || 'general'}\n**Source:** ${metadata.file_path || ''}\n\n${trimmed}`,
          metadata: {
            ...enrichedMetadata,
            chunk_index: chunkIndex,
            chunk_char_length: trimmed.length
          }
        }
      });
      chunkIndex++;
    }
  }
}

return processed;

const currentSha = $('Fetch Latest Commit SHA').first()?.json?.sha;
const qdrantResponse = $('Fetch Qdrant State SHA').first()?.json;
const storedSha = qdrantResponse?.result?.payload?.commit_sha || null;

if (!currentSha) {
  throw new Error("Could not retrieve commit SHA from GitHub API.");
}

// Compare GitHub SHA with stored Qdrant SHA
if (currentSha && currentSha === storedSha) {
  console.log(`SHA match (${currentSha}). Short-circuiting execution in 10ms.`);
  return []; // Stops execution right here cleanly!
}

console.log(`Documentation change detected! Proceeding with sync for commit (${currentSha})...`);
return [{
  json: {
    status: 'UPDATES_FOUND',
    currentSha: currentSha
  }
}];

const currentSha = $('Fetch Latest Commit SHA').first()?.json?.sha;

if (!currentSha) {
  throw new Error("Could not find commit SHA to persist.");
}

return [{
  json: {
    points: [
      {
        id: "+1234567890+1234567890",
        vector: new Array(768).fill(0),
        payload: {
          commit_sha: currentSha,
          synced_at: new Date().toISOString()
        }
      }
    ]
  }
}];
